# frozen_string_literal: true

# #564: lib/engine is generated by bin/engine-sync and proven by bin/engine-check (#563 Task 1).
require "fileutils"
require "tmpdir"
require "open3"

RSpec.describe "engine-sync / engine-check" do
  let(:root_dir) { File.expand_path("../..", __dir__) }
  let(:tmp) { Dir.mktmpdir("engine-sync") }
  let(:upstream) { File.join(tmp, "upstream") }
  let(:work) { File.join(tmp, "work") }

  after { FileUtils.remove_entry(tmp) }

  def write(base, path, text)
    full = File.join(base, path)
    FileUtils.mkdir_p(File.dirname(full))
    File.write(full, text)
  end

  def sh(*cmd, chdir: work)
    out, status = Open3.capture2e(*cmd, chdir: chdir)
    [out, status.exitstatus]
  end

  def tool(name, *args)
    sh(RbConfig.ruby, File.join(root_dir, "bin", name), "--root", work, *args)
  end

  # A tiny upstream: core files, a foreign title (must be dropped) and the two kept titles.
  def build_upstream
    write(upstream, "lib/engine.rb", "require_rel 'engine/game'\n")
    write(upstream, "lib/engine/tile.rb", "class Tile\nend\n")
    write(upstream, "lib/engine/game/base.rb", "class Base\nend\n")
    write(upstream, "lib/engine/game/g_1830.rb", "G1830\n")
    write(upstream, "lib/engine/game/g_1830/game.rb", "G1830 game\n")
    write(upstream, "lib/engine/game/g_18_oe.rb", "G18OE\n")
    write(upstream, "lib/engine/game/g_18_oe/game.rb", "G18OE game\n")
    write(upstream, "lib/engine/game/g_18_oe_uk_fr.rb", "UKFR\n")
    write(upstream, "app/other.rb", "not engine\n")
    sh("git", "init", "-q", chdir: upstream)
    sh("git", "-c", "user.name=t", "-c", "user.email=t@example.test", "add", ".", chdir: upstream)
    sh("git", "-c", "user.name=t", "-c", "user.email=t@example.test", "commit", "-q", "-m", "x", chdir: upstream)
    sh("git", "rev-parse", "HEAD", chdir: upstream).first.strip
  end

  before do
    FileUtils.mkdir_p(work)
    @sha = build_upstream
    write(work, "engine/local/0001-loading.patch", <<~PATCH)
      --- a/lib/engine.rb
      +++ b/lib/engine.rb
      @@ -1 +1 @@
      -require_rel 'engine/game'
      +Dir['engine/game/*.rb'].sort
    PATCH
  end

  it "syncs upstream@sha, drops foreign titles, applies local patches, and engine-check is green" do
    out, code = tool("engine-sync", @sha, "--upstream", upstream)
    expect(code).to eq(0), out
    expect(File.read(File.join(work, "lib/engine.rb"))).to eq("Dir['engine/game/*.rb'].sort\n")
    expect(File).to exist(File.join(work, "lib/engine/game/g_18_oe/game.rb"))
    expect(File).to exist(File.join(work, "lib/engine/game/g_18_oe_uk_fr.rb"))
    expect(File).not_to exist(File.join(work, "lib/engine/game/g_1830.rb"))
    expect(File).not_to exist(File.join(work, "lib/engine/game/g_1830"))
    expect(File).not_to exist(File.join(work, "app"))
    expect(File.read(File.join(work, "engine/PIN")).strip).to eq(@sha)
    out, code = tool("engine-check")
    expect(code).to eq(0), out
  end

  it "engine-check names a changed, a missing and an extra file" do
    tool("engine-sync", @sha, "--upstream", upstream)
    File.write(File.join(work, "lib/engine/tile.rb"), "class Tile\n  # edited\nend\n")
    File.delete(File.join(work, "lib/engine/game/base.rb"))
    write(work, "lib/engine/extra.rb", "x\n")
    out, code = tool("engine-check")
    expect(code).to eq(1)
    expect(out).to include("lib/engine/tile.rb", "lib/engine/game/base.rb", "lib/engine/extra.rb")
  end

  it "is idempotent for the same sha" do
    tool("engine-sync", @sha, "--upstream", upstream)
    before = File.read(File.join(work, "engine/MANIFEST"))
    out, code = tool("engine-sync", @sha, "--upstream", upstream)
    expect(code).to eq(0), out
    expect(File.read(File.join(work, "engine/MANIFEST"))).to eq(before)
    expect(tool("engine-check").last).to eq(0)
  end

  it "fails and leaves lib/engine untouched when a patch does not apply" do
    tool("engine-sync", @sha, "--upstream", upstream)
    write(work, "engine/patches/0001-bad.patch", "--- a/lib/engine/tile.rb\n+++ b/lib/engine/tile.rb\n@@ -1 +1 @@\n-nope\n+x\n")
    out, code = tool("engine-sync", @sha, "--upstream", upstream)
    expect(code).not_to eq(0)
    expect(out).to include("0001-bad.patch")
    expect(tool("engine-check").last).to eq(0)
  end
end
